input.command:
cd /workspace; wc -l grimoires/loa/a2a/sprint-1/adversarial-rejected-review.jsonl; python3 -I -c "
import json,sys
for l in open(sys.argv[1]):
    l=l.strip()
    if not l: continue
    try: r=json.loads(l)
    except Exception as e: print('unparseable row', e); continue
    p=r.get('payload') or {}
    print('-', r.get('reject_reason'), '|', p.get('severity'), '|', (p.get('title') or p.get('failure_mode') or '')[:120], '|', p.get('anchor') or p.get('file'))
" grimoires/loa/a2a/sprint-1/adversarial-rejected-review.jsonl; echo ---; .claude/scripts/verdict-derive.sh --help 2>&1 | head -30
